ValidationRule.errorConditionFormula:
    AND(
        NOT( $Setup.Salesforce_Library_Settings__c.Disable_VRs__c ),
        OR(
            AND(
                RecordType.DeveloperName = "ID_Ops_Assistance",
                ISPICKVAL( PRIORVALUE( Status ), "Equifax Failed"),
                OR( 
                    ISPICKVAL( Status, "Daon Failed" ),
                    ISPICKVAL( Status, "ID Ops: Daon Approved" ),
                    ISPICKVAL( Status, "Confirmed Fraud" )
                ) 
            ),
            AND(
                RecordType.DeveloperName = "Fraud_Check",
                ISPICKVAL( PRIORVALUE( Status ), "Equifax Failed"),
                OR( 
                    ISPICKVAL( Status, "Daon Failed" ),
                    ISPICKVAL( Status, "Fraud check: Daon Approved" 
                )
            ) 
        )
    )
)
